def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d < 6.0:
            if en[i] is not None and en[j] is not None:
                u = d / (1.5 * (radii[i] + radii[j]))
                w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
                contrast = (en[i] - en[j]) ** 2
                total += w * contrast / (1.0 + contrast)
                weight += w
    return total / max(weight, 1e-12)

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is None or fraction <= 0.0:
            continue
        radius = max(0.1, (props.get(element) or {}).get('covalent_radius_A') or 1.3)
        total += fraction * radius ** 3
        weight += fraction
    volume = s.get('volume_per_atom_A3') or 0.0
    if volume <= 0.0:
        count = sum(max(0.0, x.get('occupancy', 1.0) or 0.0) for x in s.get('sites') or [])
        cell_volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
        if count > 0.0 and cell_volume > 0.0:
            volume = cell_volume / count
    if volume <= 0.0 or weight <= 0.0:
        return 0.0
    return 4.1887902047863905 * total / (weight * volume)

