def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    fractions = [f for f in (s.get('composition') or {}).values() if f is not None and f > 0.0]
    total_fraction = sum(fractions)
    if total_fraction <= 0.0:
        return 0.0
    expected = sum(f * f for f in fractions) / (total_fraction * total_fraction)
    if expected >= 1.0 - 1e-12:
        return 0.0
    total = 0.0
    same = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d < 6.0:
            u = d / (1.5 * (radii[i] + radii[j]))
            w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
            total += w
            if sites[i].get('element') == sites[j].get('element'):
                same += w
    if total <= 0.0:
        return 0.0
    return (same / total - expected) / (1.0 - expected)

